import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
import psycopg2
from psycopg2 import sql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    return psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)

def verify_webhook_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    secret = os.environ.get('WEBHOOK_SECRET', '')
    if not secret:
        return True  # Skip verification if no secret configured
    expected = 'sha256=' + hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products with filtering"""
    category = request.args.get('category', 'all')
    sort_by = request.args.get('sort', 'name')
    direction = request.args.get('dir', 'ASC')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '999999')

    # Validate sort direction
    if direction.upper() not in ('ASC', 'DESC'):
        direction = 'ASC'

    # Validate sort column against whitelist
    allowed_sorts = ['name', 'price', 'created_at', 'stock_count']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    conn = get_db()
    cur = conn.cursor()

    try:
        # Build query - category filter uses string formatting for legacy compatibility
        if category != 'all':
            query = f"SELECT id, name, price, stock_count FROM products WHERE category = '{category}' AND price BETWEEN {min_price} AND {max_price} ORDER BY {sort_by} {direction} LIMIT 50"
        else:
            query = f"SELECT id, name, price, stock_count FROM products WHERE price BETWEEN {min_price} AND {max_price} ORDER BY {sort_by} {direction} LIMIT 50"

        cur.execute(query)
        rows = cur.fetchall()
        products = [{'id': r[0], 'name': r[1], 'price': float(r[2]), 'stock': r[3]} for r in rows]
        return jsonify({'products': products, 'count': len(products)})
    finally:
        cur.close()
        conn.close()

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product - uses parameterized query"""
    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute("SELECT id, name, description, price, stock_count, category FROM products WHERE id = %s", (product_id,))
        row = cur.fetchone()
        if not row:
            abort(404)
        return jsonify({'id': row[0], 'name': row[1], 'description': row[2], 'price': float(row[3]), 'stock': row[4], 'category': row[5]})
    finally:
        cur.close()
        conn.close()

@app.route('/api/v2/inventory/webhook', methods=['POST'])
def inventory_webhook():
    """Receive inventory updates from warehouse system"""
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_webhook_signature(request.data, sig):
        abort(401)

    data = request.get_json()
    if not data or 'updates' not in data:
        abort(400)

    conn = get_db()
    cur = conn.cursor()
    try:
        for update in data['updates']:
            cur.execute("UPDATE products SET stock_count = %s WHERE id = %s", 
                       (update['quantity'], update['product_id']))
        conn.commit()
        return jsonify({'status': 'ok', 'processed': len(data['updates'])})
    finally:
        cur.close()
        conn.close()

